def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            col = grid[r][c]
            if col == bg or (r, c) in seen:
                continue
            todo = [(r, c)]
            seen.add((r, c))
            cells = set()
            while todo:
                y, x = todo.pop()
                cells.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == col and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        todo.append((ny,nx))
            comps.append((col, cells))

    # A large L-shaped object is the color source. Replace the object
    # immediately nearest to it with that source color.
    def bounds(cells):
        rs = [p[0] for p in cells]
        cs = [p[1] for p in cells]
        return min(rs), max(rs), min(cs), max(cs)

    def is_l(cells):
        r0,r1,c0,c1 = bounds(cells)
        hh, ww = r1-r0+1, c1-c0+1
        if hh < 2 or ww < 2 or len(cells) != hh+ww-1:
            return False
        return any(
            all((r,c) in cells for c in range(c0,c1+1)) and
            all((y,cx) in cells for y in range(r0,r1+1))
            for r,cx in ((r0,c0),(r0,c1),(r1,c0),(r1,c1))
        )

    ls = [(col, cells) for col,cells in comps if is_l(cells)]
    if not ls:
        return [row[:] for row in grid]
    # Prefer the largest L: smaller Ls are ordinary objects.
    source_color, source = max(ls, key=lambda p: len(p[1]))
    rest = [(col,cells) for col,cells in comps if cells != source]
    if not rest:
        return [row[:] for row in grid]

    def d(a,b):
        return min(abs(r-y)+abs(c-x) for r,c in a for y,x in b)

    _, target = min(rest, key=lambda p: d(source,p[1]))
    out = [row[:] for row in grid]
    for r,c in target:
        out[r][c] = source_color
    return out
